hegemonyoffaith.css:
html[data-theme=dark] .revive-fly-card {
  z-index: 920;
}
html[data-theme=dark] .prophet-temp-card {
  z-index: 930;
}
html[data-theme=dark] .impermanence-victory-fly-card {
  z-index: 940;
}
html[data-theme=dark] #generalactions,
html[data-theme=dark] #pagemaintitle_wrap {
  z-index: 950;
}
html[data-theme=dark] .spy-modal-overlay,
html[data-theme=dark] .faith-war-log-overlay {
  z-index: 970;
}
html[data-theme=dark] #page-title {
  z-index: 980;
}
html[data-theme=dark] .dijitTooltip {
  z-index: 1000 !important;
}
html[data-theme=dark].bgaext_bright #mybelievercards .stockitem.believer-card-waiting {
  filter: var(--hand-disabled-filter) var(--ext-bright);
}
html[data-theme=dark].bgaext_bright .card-action,
html[data-theme=dark].bgaext_bright .card-back-action,
html[data-theme=dark].bgaext_bright .card-believer,
html[data-theme=dark].bgaext_bright .card-back-believer,
html[data-theme=dark].bgaext_bright .card-skill,
html[data-theme=dark].bgaext_bright .card-skill-back,
html[data-theme=dark].bgaext_bright .sect_badge_icon,
html[data-theme=dark].bgaext_bright #mybelievercards .stockitem.believer-card-ready {
  filter: var(--ext-bright);
}
html[data-theme=dark].bgaext_dark {
  --hof-ui-panel-bg: var(--dark-back);
}
html[data-theme=dark].bgaext_dark body {
  background: #574129;
}
html[data-theme=dark].bgaext_dark #overall-content {
  color: var(--light-80);
}
html[data-theme=dark].bgaext_dark #game_play_area,
html[data-theme=dark].bgaext_dark #game_play_area:before {
  background-color: #5d4d3c;
  background-blend-mode: multiply;
}
html[data-theme=dark].bgaext_dark #central_arena:has( > :is(.faith-war-board, .aoe-combat-layout, .game-end-summary-wrap)):after {
  background: var(--dark-20);
}
html[data-theme=dark].bgaext_dark #central_arena .aoe-left-owner-label,
html[data-theme=dark].bgaext_dark #central_arena .aoe-left-owner-player,
html[data-theme=dark].bgaext_dark #central_arena .aoe-owner-player,
html[data-theme=dark].bgaext_dark #central_arena .aoe-owner-sect,
html[data-theme=dark].bgaext_dark #central_arena .combat-owner-player,
html[data-theme=dark].bgaext_dark #central_arena .combat-owner-sect,
html[data-theme=dark].bgaext_dark #central_arena .combat-result-label {
  text-shadow: none;
}
html[data-theme=dark].bgaext_dark .deck_counter {
  color: var(--light-80);
  text-shadow: none;
}
html[data-theme=dark].bgaext_dark .hegemony_player_panel .panel-counter-text,
html[data-theme=dark].bgaext_dark .role-inline {
  color: var(--light-60);
}
html[data-theme=dark].bgaext_dark .hegemony_player_panel {
  background-color: var(--dark-30);
}
html[data-theme=dark].bgaext_dark .role_label,
html[data-theme=dark].bgaext_dark .hegemony_player_panel .actions_label {
  color: var(--blue-50);
}
html[data-theme=dark].bgaext_dark .hegemony_player_panel .believers_label,
html[data-theme=dark].bgaext_dark .combat-result-item.is-winner .combat-result-label,
html[data-theme=dark].bgaext_dark .initial-skill-draft-title,
html[data-theme=dark].bgaext_dark .faith-war-log-row .result.win,
html[data-theme=dark].bgaext_dark .impermanence-victory-title,
html[data-theme=dark].bgaext_dark .faith-war-banner,
html[data-theme=dark].bgaext_dark .spy-modal-action-count,
html[data-theme=dark].bgaext_dark .spy-modal-believer-count {
  color: var(--red-80);
}
html[data-theme=dark].bgaext_dark .hand-count-badge {
  background-color: var(--dark-10);
  border-color: var(--light-70);
  color: var(--light-70);
}
html[data-theme=dark].bgaext_dark .spy-modal {
  background: var(--dark-10);
  border-color: var(--dark-40);
}
html[data-theme=dark].bgaext_dark .faith-war-log-modal-list,
html[data-theme=dark].bgaext_dark .mobile-card-tooltip-content,
html[data-theme=dark].bgaext_dark .spy-modal,
html[data-theme=dark].bgaext_dark .spy-modal-section,
html[data-theme=dark].bgaext_dark .spy-modal-section h4,
html[data-theme=dark].bgaext_dark .spy-modal-title,
html[data-theme=dark].bgaext_dark .faith-war-log-title {
  color: var(--light-60);
}
html[data-theme=dark].bgaext_dark .faith-war-log-row {
  color: var(--light-50);
}
html[data-theme=dark].bgaext_dark .faith-war-log-panel {
  background: var(--dark-back);
}
html[data-theme=dark].bgaext_dark .hegemony_player_panel .panel-skill-active.is-exhausted {
  color: #9f7060;
}

schadenfreude.css:
html[data-theme=dark].bgaext_dark {
  --ext-overlay-color: #fff8;
}
html[data-theme=dark].bgaext_dark #overall-content {
  color: var(--light-80);
}
html[data-theme=dark].bgaext_dark .mf_already_played .mf_note {
  color: var(--light-60);
}
